import { test } from 'node:test';
import assert from 'node:assert/strict';
import { collect } from '../src/collector.js';

test('returns exactly target unique items', async () => {
  let call = 0;
  const batches = [['a', 'b', 'a'], ['b', 'c'], ['c', 'd', 'e']];
  const findCandidates = async () => batches[call++] ?? [];

  const result = await collect(3, findCandidates);

  assert.equal(result.length, 3);
  assert.deepEqual(new Set(result), new Set(['a', 'b', 'c']));
});

test('stops calling findCandidates once target is reached', async () => {
  let calls = 0;
  const findCandidates = async () => { calls++; return ['x', 'y', 'z']; };

  await collect(3, findCandidates);

  assert.equal(calls, 1);
});

test('handles overlapping results across rounds', async () => {
  let call = 0;
  const findCandidates = async () => call++ === 0 ? ['a', 'b'] : ['b', 'c'];

  const result = await collect(3, findCandidates);

  assert.equal(result.length, 3);
  assert.deepEqual(new Set(result), new Set(['a', 'b', 'c']));
});

test('slices to exactly target when last batch overshoots', async () => {
  const findCandidates = async () => ['a', 'b', 'c', 'd', 'e'];

  const result = await collect(2, findCandidates);

  assert.equal(result.length, 2);
});
